def pending_invites_to_assignments(apps, schema_editor):
    """An approved headhunter still deciding on an invite is now on the job, with their channel.

    One Sparktal removed earlier is put back on the same assignment. Invites that were declined,
    cancelled or accepted change nothing: an accepted one already has its assignment. Neither
    does one on a job that is not live (the old `open_invites`: active, not deleted, with a
    bounty): the headhunter could not answer it any more.
    """
    Job = apps.get_model("jobs", "Job")
    JobInvite = apps.get_model("jobs", "JobInvite")
    JobAssignment = apps.get_model("jobs", "JobAssignment")
    Channel = apps.get_model("chat", "Channel")
    live = Job.objects.filter(status="active", deleted_at__isnull=True).filter(
        Q(bounty_type="pct", bounty_pct__isnull=False)
        | Q(bounty_type="fixed", bounty_amount__isnull=False)
    )
    pending = JobInvite.objects.filter(status="pending", recruiter__status="approved", job__in=live)
    for job_id, recruiter_id in pending.values_list("job_id", "recruiter_id").iterator():
        assignment, created = JobAssignment.objects.get_or_create(
            job_id=job_id, recruiter_id=recruiter_id, defaults={"left_at": None}
        )
        if not created and assignment.left_at is not None:
            assignment.left_at = None
            assignment.save(update_fields=["left_at"])
        Channel.objects.get_or_create(job_id=job_id, recruiter_id=recruiter_id)


